BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{}',true),set_config('request.jwt.claim.sub','',true);
DO $check$
DECLARE checks integer:=0;
BEGIN
 BEGIN PERFORM public.event_host_list(NULL,NULL); RAISE EXCEPTION 'signedout_host_list_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 BEGIN PERFORM public.event_host_get(NULL); RAISE EXCEPTION 'signedout_host_get_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 BEGIN PERFORM public.event_host_receipt(NULL); RAISE EXCEPTION 'signedout_host_receipt_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 BEGIN PERFORM public.table_hold_status(NULL,NULL); RAISE EXCEPTION 'signedout_hold_status_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 BEGIN PERFORM public.table_identity_get(NULL,NULL); RAISE EXCEPTION 'signedout_identity_get_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 BEGIN PERFORM public.event_host_guest_save(NULL,NULL,NULL,NULL,NULL,NULL,NULL); RAISE EXCEPTION 'signedout_guest_save_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 BEGIN PERFORM public.table_hold_create(NULL,NULL,NULL,NULL,NULL); RAISE EXCEPTION 'signedout_hold_create_accepted'; EXCEPTION WHEN insufficient_privilege THEN checks:=checks+1;END;
 IF checks<>7 THEN RAISE EXCEPTION 'signedout_authority_checks_incomplete';END IF;
END $check$;
SELECT jsonb_build_object('signedout_current_session_refusals',7,'current_role',current_user,'fixture_rows_created',0,'customer_mutations',0,'transaction','rollback') AS result;
ROLLBACK;
